local config = {
  ui_story_30860401_1_dialog_content = "¿Así que lo que dices, es que has encontrado <color=#FFB400>flores blancas> en el Colossus?",
  ui_story_30860401_2_dialog_content = "Tu flor blanca, para ser específico.",
  ui_story_30860401_3_dialog_content = "Me he levantado temprano a entrenar estos últimos días.",
  ui_story_30860401_4_dialog_content = "Y comencé a sentir un olor extraño y floral.",
  ui_story_30860401_5_dialog_content = "Finalmente, esta mañana, encontré la razón del olor.",
  ui_story_30860401_6_dialog_content = "Alguien había colocado estas misteriosas flores blancas en las esquinas del Colossus...",
  ui_story_30860401_7_dialog_content = "Pero hay una cantidad de personas aquí con flores.",
  ui_story_30860401_8_dialog_content = "Cierto, hay una cantidad de personas con flores en el Colossus...",
  ui_story_30860401_X8_dialog_content = "Hiiro, Nikinis, Jola...",
  ui_story_30860401_9_dialog_content = "¡Pero tú eres el único con este tipo de flor!",
  ui_story_30860401_10_dialog_content = "Estas seguro que soy yo, ¿no?... ¿Cómo estás tan seguro?",
  ui_story_30860401_11_dialog_content = "¡Tengo pruebas!",
  ui_story_30860401_17_dialog_content = "¿Esta es tu idea de una broma? Primero pones flores en la cabeza del Señor, ¿luego las siembras en todo el Colossus?",
  ui_story_30860401_18_dialog_content = "¡No!",
  ui_story_30860401_19_dialog_content = "Claro que no ♩",
  ui_story_30860401_20_dialog_content = "Quien las sembró♫♩",
  ui_story_30860401_21_dialog_content = "Inclinan su cabeza <color=#FFB400>oración</color>.",
  ui_story_30860401_22_dialog_content = "¡Y ofrecen sus <color=#FFB400>condolencias</color>!",
  ui_story_30860401_23_dialog_content = "(¿Oración? ¿Condolencia? ¡¿Por qué suena como una <color=#FFB400>funeraria</color>?!)",
  ui_story_30860401_24_dialog_content = "¡Es <color=#FFB400>Uriah</color>!",
  ui_story_30860401_25_dialog_content = "¡No me engañas!",
  ui_story_30860401_26_dialog_content = "Investigué un poco y, ¡estas flores blancas son exactamente iguales a las de tus enredaderas de flores!",
  ui_story_30860401_27_dialog_content = "¿Me estás condenando por esto?",
  ui_story_30860401_28_option_content = "¡No me refiero a eso!",
  ui_story_30860401_29_dialog_content = "Solo quería preguntarte sobre ello...",
  ui_story_30860401_30_option_content = "No estás siendo acusado de un crimen o algo...",
  ui_story_30860401_31_dialog_content = "Estaba curioso, es todo.",
  ui_story_30860401_32_dialog_content = "Todas esas flores cubriendo el Colossus...",
  ui_story_30860401_33_dialog_content = "Es la primera vez que veo a alguien sembrando flores en el Colossus.",
  ui_story_30860401_34_dialog_content = "Ya que estás tan seguro que he sido yo, déjame expresar mis disculpas.",
  ui_story_30860401_35_dialog_content = "Aunque esto no sea algo que deba permanecer guardado.",
  ui_story_30860401_36_dialog_content = "¿Así que fuiste tu quién sembró estas flores?",
  ui_story_30860401_37_dialog_content = "Es solo una parte de mis oraciones. ¿Espero no estés ofendido?",
  ui_story_30860401_38_option_content = "Claro, no me importa...",
  ui_story_30860401_39_dialog_content = "Me alegra ver tantas flores después de entrenar todo el día.",
  ui_story_30860401_40_option_content = "Solo me preocupa que lastime a Soroz...",
  ui_story_30860401_41_dialog_content = "Por favor mantén la calma, estas flores no crecen naturalmente - hasta sus tallos son hechos de mi enredadera.",
  ui_story_30860401_42_dialog_content = "Las he colocado por todo Colossus como muestra de mi respeto.",
  ui_story_30860401_43_dialog_content = "Ahora que lo mencionas, tus enredaderas de flores también tienen esas flores blancas. ¿Son tus favoritas?",
  ui_story_30860401_44_dialog_content = "No es que sean mis favoritas, pero...",
  ui_story_30860401_45_dialog_content = "¿Entiendes el significado de estas flores?",
  ui_story_30860401_46_option_content = "La verdad no...",
  ui_story_30860401_47_dialog_content = "¿Qué significa?",
  ui_story_30860401_48_option_content = "Algo así, sí...",
  ui_story_30860401_49_dialog_content = "¿Así que tu poder tiene algo que ver con su significado?",
  ui_story_30860401_50_dialog_content = "Esta flor simboliza “<color=#FFB400>una despedida trágica</color>”.",
  ui_story_30860401_51_dialog_content = "¿Tu poder está atado a despedida?",
  ui_story_30860401_52_dialog_content = "¿Está relacionado a tu familia?",
  ui_story_30860401_53_dialog_content = "Sí... y a mí, también.",
  ui_story_30860401_54_dialog_content = "Has sido tan amable, escuchándome todo este tiempo. Te tendré en mis oraciones día y noche.",
  ui_story_30860401_55_dialog_content = "A veces no sé si eres serio o no.",
  ui_story_30860401_56_dialog_content = "Ejem, de todos modos... Como Navegador, es mi responsabilidad entender a mi tripulación lo más que pueda, ¿no estás de acuerdo?",
  ui_story_30860401_57_dialog_content = "De verdad quisiera saber, estaría más que feliz de contarte sobre mi pasado.",
  ui_story_30860401_58_dialog_content = "Pero a cambio, ¿me contarías sobre las cosas por las que lloras?",
  ui_story_30860401_59_dialog_content = "¿Yo? Alto, ¿qué tiene que ver eso conmigo?",
  ui_story_30860401_60_dialog_content = "Tu familia, por ejemplo. Las cosas que quieres proteger... Las cosas de las que debes despedirte...",
  ui_story_30860401_61_dialog_content = "Todo eso es historia antigua... Además, no recuerdo mucho sobre mi familia.",
  ui_story_30860401_62_dialog_content = "Cualquier cosa. ¿Por favor?",
  ui_story_30860401_63_dialog_content = "Mmm... Bueno, me imagino que has escuchado que Soroz me creó toda mi vida, ¿no?",
  ui_story_30860401_64_dialog_content = "Ah si, el maravilloso Blanco Colossus.",
  ui_story_30860401_65_dialog_content = "Por 17 años, crecí aquí. Primero, no entendía nada sobre el mundo exterior.",
  ui_story_30860401_66_dialog_content = "Todas las imágenes en mi mente eran fragmentos de memorias que tuve de Soroz...",
  ui_story_30860401_67_dialog_content = "Como estaba escondido en este Colossus...",
  ui_story_30860401_68_dialog_content = "Y como mi gente murió peleando contra los Eclipsites...para protegerme.",
  ui_story_30860401_69_dialog_content = "De nuevo, estas memorias estaban plantadas en mi cerebro. No tengo forma de confirmar si son reales o no...",
  ui_story_30860401_70_dialog_content = "Aprendí de esto, también.",
  ui_story_30860401_71_dialog_content = "Como algo de lo que no sabes.",
  ui_story_30860401_72_dialog_content = "Algo... ¿De lo que no sé?",
  ui_story_30860401_73_dialog_content = "¿Recuerdas <color=#FFB400>la marca roja en el ala de Colossus</color>?",
  ui_story_30860401_74_option_content = "Si, recuerdo...",
  ui_story_30860401_75_dialog_content = "Una vez que estaba limpiando Colossus, Vice me hizo pasar un mal rato por lo mal que lucía Soroz. Le causó enojo por algún tiempo.",
  ui_story_30860401_76_option_content = "No recuerdo...",
  ui_story_30860401_77_dialog_content = "Pero hace mucho tiempo, estaba esta marca en el Colossus que no podía limpiar sin importar que tanto lo intentara.",
  ui_story_30860401_78_dialog_content = "Y cuentan una historia. No son solo suciedad en una máquina.",
  ui_story_30860401_79_dialog_content = "¿Y qué era?",
  ui_story_30860401_80_dialog_content = "En todas esas memorias fragmentadas...¿estás seguro que no las has visto antes?",
  ui_story_30860401_81_dialog_content = "Alto, será posible...",
  ui_story_30860401_82_dialog_content = "Precisamente. Esa no era una mancha ordinaria, era <color=#FFB400>sangre</color> de tu compañero Celestita.",
  ui_story_30860401_83_dialog_content = "Soroz nunca les ha olvidado. Es un símbolo de su historia contigo mientras crecías.",
  ui_story_30860401_84_dialog_content = "¿Cómo supiste de esto, Uriah?",
  ui_story_30860401_85_dialog_content = "Cuando llegué por primera vez a Colossus, me crucé con este <color=#FFB400>diario</color>...",
  ui_story_30860401_86_dialog_content = "Pertenece a alguien que ya no está con nosotros... Sus páginas están llenas de historias de ti y tu gente.",
  ui_story_30860401_87_dialog_content = "Por favor discúlpame, hice mal en leerlo.",
  ui_story_30860401_88_dialog_content = "No tenía idea cuando lo encontré, y he estado esperando por esta oportunidad de pasarlo a ti.",
  ui_story_30860401_89_dialog_content = "He orado por este momento por tanto tiempo...",
  ui_story_30860401_90_dialog_content = "Y ahora, creo que es el momento correcto de devolverlo a ti.",
  ui_story_30860401_91_dialog_content = "Este diario, y estas flores... Por favor acéptalas.",
  ui_story_30860401_92_dialog_content = "Espero que llores y ores por tu gente que ha caído, y darles una despedida adecuada.",
  ui_story_30860401_93_dialog_content = "*Toma flores blancas*",
  ui_story_30860401_94_dialog_content = "De acuerdo a ese diario, hoy es el día de luto por los difuntos...",
  ui_story_30860401_95_dialog_content = "Una despedida adecuada... Es la primera vez que escucho sobre ese día festivo.",
  ui_story_30860401_96_dialog_content = "Debería hacer algo especial en su recuerdo... Gracias.",
  ui_story_30860401_97_dialog_content = "Así como todos los demás, te mantengo en mis oraciones, también.",
  ui_story_30860401_98_dialog_content = "Dilo... ¿Por qué siento que estoy olvidando algo?",
  ui_story_30860401_99_dialog_content = "¿Lo estás?",
  ui_story_30860401_100_dialog_content = "¿Lo estoy?",
  ui_story_30860401_101_dialog_content = "No lo creo. Deberías descansar. Oraré por ti hoy antes de ir a la cama.",
  ui_story_30860401_X101_dialog_content = "Hasta la próxima.",
  ui_story_30860401_102_dialog_content = "¡Ahora lo recuerdo! Se supone que debes contarme sobre tu pasado...",
  ui_story_30860401_103_dialog_content = "¿Dónde ha ido?",
  ui_story_30860401_104_dialog_content = "¡Uriah!",
  ui_story_30860601_1_dialog_content = "¿Puedes escuchar esos <color=#FFB400>sonidos</color>?",
  ui_story_30860601_2_dialog_content = "¿Sonidos?",
  ui_story_30860601_3_dialog_content = "Las olas rodando en la orilla, las gaviotas llamando mientras juegan.",
  ui_story_30860601_4_dialog_content = "Las largas hojas de las palmeras se balancean con el viento, y el sonido de los pies caminando por la arena.",
  ui_story_30860601_5_dialog_content = "Todos estos sonidos rebosan de la vibrante energía del verano. Ah, es tan reconfortante...",
  ui_story_30860601_6_dialog_content = "Escucha con atención.",
  ui_story_30860601_7_dialog_content = "¡Vaya, tienes razón! Cuando presto atención, ¡hay tantos sonidos a nuestro alrededor!",
  ui_story_30860601_8_dialog_content = "Sí.",
  ui_story_30860601_9_dialog_content = "(No se ve esta mirada en la cara de Uriah todos los días).",
  ui_story_30860601_10_dialog_content = "(Normalmente, se ve tan digna y elegante, y toda envuelta de pies a cabeza... como una escultura, o algo así).",
  ui_story_30860601_11_dialog_content = "(Pero parece que ni siquiera esa expresión seria suya puede aguantar en la playa).",
  ui_story_30860601_12_dialog_content = "Sé lo que estás pensando, que rara vez me ves así.",
  ui_story_30860601_13_dialog_content = "Pero estas prendas son perfectas para alejar el calor del verano.",
  ui_story_30860601_14_dialog_content = "¿Crees que me convienen?",
  ui_story_30860601_15_option_content = "¡Absolutamente!",
  ui_story_30860601_16_dialog_content = "Aunque están diseñadas para la natación, aún tienen el estilo elegante y la calidad de Lumopolis.",
  ui_story_30860601_17_dialog_content = "Cuando los llevas, da a todos una impresión de gracia y piedad. ¡Cómo una perla del mar!",
  ui_story_30860601_18_dialog_content = "Yo... no estoy seguro de si lo que digo tiene sentido o no.",
  ui_story_30860601_19_dialog_content = "Nunca esperé recibir un elogio tan sincero de su parte. Tienes mi gratitud.",
  ui_story_30860601_20_dialog_content = "Para ser sincero, cuando llegamos a la playa, pensé que aún llevarías tu atuendo de monja.",
  ui_story_30860601_21_option_content = "Es un poco sorprendente.",
  ui_story_30860601_22_dialog_content = "Estas prendas son realmente diferentes de lo que se suele llevar.",
  ui_story_30860601_23_dialog_content = "En mi mente, siempre llevas tu atuendo de monja.",
  ui_story_30860601_24_dialog_content = "Debo vestirme solemnemente cuando estoy en oración.",
  ui_story_30860601_25_dialog_content = "Cuido meticulosamente mi ropa, igual que cuido mis flores blancas.",
  ui_story_30860601_26_dialog_content = "Es una señal de respeto a los heridos, a los difuntos y a los seres queridos que han dejado atrás.",
  ui_story_30860601_27_dialog_content = "Creo que nadie desea ver a alguien vestido con indiferencia mientras lo conducen por las dificultades de la vida. ¿Estoy en lo cierto?",
  ui_story_30860601_28_dialog_content = "Sin embargo, ahora mismo estoy fuera de servicio.",
  ui_story_30860601_29_dialog_content = "¿Por qué has decidido venir al Ocean Sovereign?",
  ui_story_30860601_30_dialog_content = "He venido por invitación de Lady Carleen.",
  ui_story_30860601_31_dialog_content = "Es una chica amable y considerada. Le preocupa que trabaje demasiado y desea que me divierta más.",
  ui_story_30860601_32_dialog_content = "Nunca podría rechazar una invitación tan amable y considerada como ésta.",
  ui_story_30860601_33_dialog_content = "Además... Hace tiempo que conozco el Ocean Sovereign y siempre he querido verlo con mis propios ojos.",
  ui_story_30860601_34_dialog_content = "Creo que incluso podría descubrir <color=#FFB400>el sonido que estoy buscando</color>.",
  ui_story_30860601_35_dialog_content = "¿Conoces el Ocean Sovereign, PlayerName?",
  ui_story_30860601_36_dialog_content = "Bonacie ya me habló de él. El Soberano del Océano es una ceremonia que dejaron los aurorians que vivían en esta playa.",
  ui_story_30860601_37_dialog_content = "Es una competición que pone a prueba la <color=#FFB400>fuerza</color>, <color=#FFB400>conocimiento</color> y <color=#FFB400>valentía</color> de los participantes, para determinar un ganador.",
  ui_story_30860601_38_dialog_content = "Se supone que el festival bendice este lugar con buen tiempo.",
  ui_story_30860601_39_dialog_content = "Tienes toda la razón, pero ¿sabes por qué el Soberano del Océano es una prueba de esas tres cualidades?",
  ui_story_30860601_40_dialog_content = "¿Ah? ¿Hay una historia detrás?",
  ui_story_30860601_41_dialog_content = "\"Los sonidos llevan las historias del pasado\".",
  ui_story_30860601_42_dialog_content = "Hace mucho tiempo, los habitantes de esta costa dependían de los dones del cielo y el mar para vivir.",
  ui_story_30860601_43_dialog_content = "Con el tiempo, llegaron a dar por sentados estos dones.",
  ui_story_30860601_44_dialog_content = "Entonces, un día, el cielo dejó de traer lluvia, el mar se retiró y todo lo que vivía en las aguas murió como resultado.",
  ui_story_30860601_45_dialog_content = "A lo lejos, un imponente castillo surgió de las profundidades del mar, y las nubes oscuras pronto cubrieron toda la Costa Celestial.",
  ui_story_30860601_46_dialog_content = "Sólo si se completaban las pruebas de las tres diosas de la Fuerza, el Conocimiento y la Valentía, la costa volvería a su estado original.",
  ui_story_30860601_47_dialog_content = "Normalmente, aquí es donde aparece un héroe para salvar el día.",
  ui_story_30860601_48_dialog_content = "Precisamente.",
  ui_story_30860601_49_dialog_content = "Para salvar el litoral, un <color=#FFB400>rey</color> de la época dio un paso adelante con decisión.",
  ui_story_30860601_50_dialog_content = "Utilizando su inquebrantable fuerza, escaló el castillo.",
  ui_story_30860601_51_dialog_content = "Con su mente inteligente, superó a la Diosa del Conocimiento en su propio juego.",
  ui_story_30860601_52_dialog_content = "Y finalmente, con su noble valor, superó sus mayores temores y pasó la prueba de la Diosa de la Valentía.",
  ui_story_30860601_53_dialog_content = "Al final, el rey se ganó el favor de las tres diosas.",
  ui_story_30860601_54_dialog_content = "Tras recibir su bendición, la lluvia volvió a caer del cielo y el mar volvió a subir por la costa, trayendo consigo la vida.",
  ui_story_30860601_55_dialog_content = "Las diosas usaron su poder para devolver al rey a su propio reino.",
  ui_story_30860601_56_dialog_content = "Sin embargo, el mundo está en constante cambio, y ya no era el mismo que durante su reinado.",
  ui_story_30860601_57_dialog_content = "Habían pasado cien años, las familias y los amigos habían abandonado el mundo hacía tiempo.",
  ui_story_30860601_58_dialog_content = "En su dolor, el rey se convirtió en una piedra en lo alto de un acantilado, donde siempre podrá proteger el futuro de su reino.",
  ui_story_30860601_59_dialog_content = "Aunque sus seres queridos ya no estaban con él, las palabras de sus actos sobrevivieron al paso del tiempo. En honor al rey y a las tres diosas, surgió el Soberano del Océano.",
  ui_story_30860601_60_dialog_content = "Para la población local, la fuerza, el conocimiento y la valentía son presumiblemente las tres cualidades más admirables en una persona.",
  ui_story_30860601_61_dialog_content = "Suena como un cuento de hadas.",
  ui_story_30860601_62_dialog_content = "¿Insinúas que la historia no te parece real?",
  ui_story_30860601_X62_dialog_content = "Tal vez un poco...",
  ui_story_30860601_63_dialog_content = "Aunque la historia parezca inventada, el Soberano del Océano es algo muy real.",
  ui_story_30860601_64_dialog_content = "También lo son las pruebas de fuerza, conocimiento y valentía.",
  ui_story_30860601_65_dialog_content = "(Aunque las \"pruebas\" son sólo concursos de voleibol, ajedrez y canto...)",
  ui_story_30860601_66_dialog_content = "¿Qué te parece la historia, Uriah?",
  ui_story_30860601_67_dialog_content = "¿Qué es lo que pienso? Bien...",
  ui_story_30860601_68_dialog_content = "Vamos, no hay nada especial aquí.",
  ui_story_30860601_69_dialog_content = "¿Qué es toda esa de conmoción allá?",
  ui_story_30860601_70_dialog_content = "Ya te dije que este tipo de eventos sólo sirven para estafar a los turistas.",
  ui_story_30860601_71_dialog_content = "Hacen un gran escándalo sobre algún tema, y luego organizan un montón de eventos sin sentido para hacer negocio.",
  ui_story_30860601_72_dialog_content = "Después, montan puestos por todas partes para sacar provecho de la situación. Granizado, bebidas frías, trajes de baño, productos de playa...",
  ui_story_30860601_73_dialog_content = "Al final, el objetivo de estas cosas es hacer que saquemos la cartera y paguemos.",
  ui_story_30860601_74_dialog_content = "Es decir, nadie cree en verdad en esa mierda de leyenda \"Soberano del Océano\", ¿verdad? O esas tonterías sobre la fuerza, la valentía y el conocimiento...",
  ui_story_30860601_75_dialog_content = "(No puedo evitar pensar que tiene razón...)",
  ui_story_30860601_76_dialog_content = "Eso es suficiente.",
  ui_story_30860601_77_dialog_content = "...",
  ui_story_30860601_78_dialog_content = "¿Estás bien, Uriah?",
  ui_story_30860601_79_dialog_content = "Sí. Lo que ha dicho es, en efecto, correcto.",
  ui_story_30860601_80_dialog_content = "No importa lo que digamos o pensemos, las leyendas como ésta están destinadas a desaparecer con el tiempo, dejando sólo las apariencias de lo que una vez significaron.",
  ui_story_30860601_81_dialog_content = "El Soberano del Océano, el rey de piedra, el castillo en el mar... todos ellos existen en la imaginación de la gente, y cambiarán y se desvanecerán con el tiempo.",
  ui_story_30860601_82_dialog_content = "Qué pena... Definitivamente no es el sonido que esperaba escuchar.",
  ui_story_30860601_83_dialog_content = "¡Uriah!",
  ui_story_30860601_84_dialog_content = "¿Si?",
  ui_story_30860601_85_dialog_content = "Yo... ¡Estoy dispuesto a creer en la historia!",
  ui_story_30860601_86_dialog_content = "¿PlayerName?",
  ui_story_30860601_87_dialog_content = "Porque... <size=45>¡Creo que es realmente romántico!</size>",
  ui_story_30860601_88_dialog_content = "Para proteger su patria, el rey pasó por tantas dificultades... ¡Demostró que su fuerza, conocimiento y valentía eran reales!",
  ui_story_30860601_89_dialog_content = "Y aunque sus pruebas cambiaron el curso de su vida, no se arrepintió, e incluso se convirtió en piedra para seguir protegiendo esta costa...",
  ui_story_30860601_90_dialog_content = "Si el Soberano del Océano proviene de este tipo de historia, ¡tiene que ser significativo!",
  ui_story_30860601_91_dialog_content = "Mmm... ¿Así que, así es como te sientes, PlayerName?",
  ui_story_30860601_92_dialog_content = "(Parece que Uriah está sumido en sus pensamientos. ¿He dicho algo que no debía?)",
  ui_story_30860601_93_dialog_content = "No te pongas tan nervioso, PlayerName. El sonido de tu voz diciendo lo que piensas es poderoso y persuasivo.",
  ui_story_30860601_94_dialog_content = "Además, creo que tienes una interpretación muy acertada de la historia. Este es el tipo de sonido que me gusta escuchar.",
  ui_story_30860601_95_dialog_content = "¿Sabes que las caracolas también pueden retener sonidos?",
  ui_story_30860601_96_dialog_content = "Una caracola almacena hermosos ecos en lo más profundo de su espiral. Cuando le hagamos una pregunta, responderá enseguida.",
  ui_story_30860601_97_dialog_content = "Quiero conservar el sonido de tu voz, así que por favor... ¡dice las palabras que me acabas de decir en esta caracola!",
  ui_story_30860601_98_dialog_content = "¿En la concha...?",
  ui_story_30860601_99_dialog_content = "(¡¿Por qué todo el mundo está mirando?! Me siento un poco raro de repente...)",
  ui_story_30860601_100_dialog_content = "(¡Pero si es por Uriah... lo haré!)",
  ui_story_30860601_101_dialog_content = "<size=45>¡Creo que la historia del Soberano del Océano es súper romántica!</size>",
  ui_story_30860601_102_dialog_content = "Huh, no pensé que hubiera gente tan crédula en el mundo.",
  ui_story_30860601_103_dialog_content = "Vamos...",
  ui_story_30860601_104_dialog_content = "Si, claro...",
  ui_story_30860601_105_dialog_content = "(Pero creo que la historia del Soberano del Océano también es súper romántica...)",
  ui_story_30860601_106_dialog_content = "Gracias, PlayerName.",
  ui_story_30860601_107_dialog_content = "Yo también me sorprendí al ver esta faceta tuya. Sorprendida, pero feliz.",
  ui_story_30860601_108_dialog_content = "Para ser sincera, sé que estas historias no son necesariamente ciertas.",
  ui_story_30860601_109_dialog_content = "Pero me enfrento al dolor y al sufrimiento reales casi todos los días, así que he llegado a apreciar la pequeña alegría que pueden proporcionar los cuentos de ficción como éste.",
  ui_story_30860601_110_dialog_content = "Bueno, si tú eres feliz, ¡yo también me alegro!",
  ui_story_30860601_111_dialog_content = "¿Cómo podría ser infeliz si tú estás aquí?",
  ui_story_30860601_112_dialog_content = "El verdadero significado de las fiestas y los festivales reside en lo que son capaces de transmitir de generación en generación.",
  ui_story_30860601_113_dialog_content = "Para nosotros, su valor reside en <color=#FFB400>lo que creemos</color>.",
  ui_story_30860601_114_dialog_content = "Ya he encontrado crédito en algo que vale la pena.",
  ui_story_30860601_115_dialog_content = "Y ese \"algo\" es nuestra elección de creer en esas <color=#FFB400>cualidades amables y honestas</color>.",
  ui_story_30860601_116_dialog_content = "Fuerza, conocimiento y valentía.",
  ui_story_30860601_117_dialog_content = "En conclusión, creo que un poco de romanticismo puede conducir a una vida más larga y feliz.",
  ui_story_30860601_118_dialog_content = "También creo que alguien como tú vivirá una vida de felicidad, sin importar las dificultades que puedan surgir.",
  ui_story_30860601_119_dialog_content = "Terminemos aquí nuestro paseo por hoy. Deberíamos volver y descansar un rato.",
  ui_story_30860601_120_dialog_content = "¡Seguro! Vamos a hacer nuestro camino de regreso, entonces.",
  ui_story_30860601_121_dialog_content = "Ah, y una cosa más.",
  ui_story_30860601_122_dialog_content = "<color=#e8d9bb>Uriah coge la caracola y le susurra algo.</color>",
  ui_story_30860601_123_dialog_content = "¿Uriah?",
  ui_story_30860601_124_dialog_content = "Simplemente estaba grabando lo que más quería decir en este momento.",
  ui_story_30860601_125_dialog_content = "Pero es un secreto. Tal vez algún día puedas escucharlo desde el interior de esta concha.",
  ui_story_30860601_126_dialog_content = "“Gracias, PlayerName. Este es el sonido que más quería escuchar hoy\"."
}
return config
